void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
  if (n < 3) return;
  /* An edge crosses a scanline at most once, so n slots always suffice. The
   * heap is only used for big polygons, to keep the task stack small. */
  double stack_xs[64];
  double *xs = stack_xs;
  if (n > 64) {
    xs = (double *)malloc((size_t)n * sizeof(double));
    if (!xs) return;
  }
  wide_t ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
  }
  if (ymin < 0) ymin = 0;
  if (ymax >= c->h) ymax = c->h - 1;
  for (wide_t yy = ymin; yy <= ymax; yy++) {
    int nx = 0;
    double sy = yy + 0.5;
    for (int i = 0, j = n - 1; i < n; j = i++) {
      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
        double t = (sy - yi) / (yj - yi);
        xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
      }
    }
    if (nx > SORT_INSERTION_MAX) {
      qsort(xs, (size_t)nx, sizeof(double), compare_doubles);
    } else {
      for (int a = 1; a < nx; a++)
        for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
          double tmp = xs[b];
          xs[b] = xs[b - 1];
          xs[b - 1] = tmp;
        }
    }
    for (int k = 0; k + 1 < nx; k += 2)
      hspan(c, (wide_t)ceil(xs[k] - 0.5), (wide_t)ceil(xs[k + 1] - 0.5) - 1, yy,
            color);
  }
  if (xs != stack_xs) free(xs);
}

/* Visible part of the rect as [x0,x1) x [y0,y1) in canvas coordinates; false
 * if none of it is visible. */

#include "x11shim/arc.h"

#include <math.h>
#include <stdlib.h>

#define FULL_SWEEP (360 * 64)
#define DEGREES_TO_RADIANS 0.017453292519943295f

static int sweep_of(int angle2) {
  if (angle2 > FULL_SWEEP) return FULL_SWEEP;
  if (angle2 < -FULL_SWEEP) return -FULL_SWEEP;
  return angle2;
}

/* About one point every two pixels along the larger radius. */
int arc_point_count(unsigned w, unsigned h, int angle2) {
  const int sweep = sweep_of(angle2);
  if (sweep == 0) return 0;
  const float radius = (float)(w > h ? w : h) / 2.0f;
  const float sweep_radians = (float)abs(sweep) / 64.0f * DEGREES_TO_RADIANS;
  const float n = ceilf(sweep_radians * radius / 2.0f) + 1.0f;
  if (n < 2.0f) return 2;
  return n > (float)ARC_MAX_POINTS ? ARC_MAX_POINTS : (int)n;
}

int arc_points(int x, int y, unsigned w, unsigned h, int angle1, int angle2,
               int *xy, int max_points) {
  int n = arc_point_count(w, h, angle2);
  if (n > max_points) n = max_points;
  if (n < 2) return n < 0 ? 0 : n;
  const float cx = (float)x + (float)w / 2.0f, cy = (float)y + (float)h / 2.0f;
  const float rx = (float)w / 2.0f, ry = (float)h / 2.0f;
  const float start = (float)angle1 / 64.0f * DEGREES_TO_RADIANS;
  const float sweep = (float)sweep_of(angle2) / 64.0f * DEGREES_TO_RADIANS;
  for (int i = 0; i < n; i++) {
    const float a = start + sweep * (float)i / (float)(n - 1);
    xy[2 * i] = (int)lrintf(cx + rx * cosf(a));
    xy[2 * i + 1] = (int)lrintf(cy - ry * sinf(a));
  }
  return n;
}

